let group = MultiThreadedEventLoopGroup(numberOfThreads: System.coreCount)
let bootstrap = ServerBootstrap(group: group)          // one selector per loop thread
    .serverChannelOption(ChannelOptions.backlog, value: 256)
    .childChannelInitializer { channel in
        channel.pipeline.addHandler(EchoHandler())      // the handler registry is the pipeline
    }
let channel = try bootstrap.bind(host: "0.0.0.0", port: 8080).wait()
try channel.closeFuture.wait()                          // the loops dispatch for the app's lifetime
